// Traduccion al ingles de las referencias que arma el codigo (lo arma tools/build-catalog.mjs desde tools/i18n/ref/*.tsv). Clave: hashStr del texto en español.
export const REF_EN = {
  "iy5i5z8": "You type",
  "n1v6258": "What it does",
  "1pc1vv17": "Example",
  "brz0lm5": "What you see",
  "s9v02ii": "7. Text and calculation",
  "d41tud78": "Texts that calculate: assignments, outputs, formulas with AsciiMath, vectors and matrices, your own functions and the reading order of the page. Examples with a result are checked against the app engine in the automated tests (`test/calcref.test.mjs`).",
  "1hbvhuu2y": "The full list of functions and operators, with examples, is in [Functions and operators](funciones.md).",
  "1i1ax2e3g": "[← 6. Dimensions](06-cotas.md) · [Index](README.md) · [8. Splines and paths (cams and trajectories) →](08-splines-y-trazados.md)",
  "53205kl": "Write a text (T)",
  "19u410t6r": "Tap where the insertion point goes and type right there, no dialog. What you type is an <b>equation</b>: it is saved as a <code>$$…$$</code> block, so you do not type the delimiters (you see them in the text properties, double tap).",
  "1u8x0j85": "Key",
  "pyrz7yc": "<b>Enter</b>",
  "15ays801f": "Draws what you typed and opens another entry right below.",
  "3wkdq1i": "<b>Shift+Enter</b>",
  "k02sor1a": "Another line in the same block (another equation).",
  "mxopixa": "<b>Esc</b>",
  "1cdj2bwp": "Discards what you are typing.",
  "10igfj0x": "<b>Enter</b> on an empty entry",
  "1nox5311x": "Finishes. Changing tool also finishes, and draws what you typed.",
  "2044hjj": "Tap elsewhere",
  "1jn2xlj16": "Draws what you typed and moves the entry there.",
  "uhehv12": "<code>\"</code> or a space at the start",
  "3iko3y4z": "Plain text instead of an equation (the <code>“</code> quotes of the iPad keyboard also work; the quote or the space is not saved). See \"Plain text, formulas and literals\".",
  "1no0vvup": "<code>%</code> at the start",
  "1ovgyc1q2": "<b>Script</b>: a function written as a program, with indentation (see <a href=\"funciones.md#programs\" data-help=\"funcs\" data-topic=\"Programs\">Programs</a> in Functions). The first line is the signature (<code>%suma2(n):</code>) and below it, indented: <code>s:0</code> assigns a local variable, <code>for i in 1..n:</code>, <code>while condición:</code> and <code>if c:</code> / <code>elif c:</code> / <code>else:</code> open a block with more indentation, <code>g(x): …</code> defines a local function and <code>#</code> comments; <code>break</code> exits the for or while, <code>continue</code> moves on to the next iteration and <code>return x</code> ends with the value x; otherwise, the last line is the value. Enter keeps the indentation (and increases it after <code>:</code>), Tab indents and Shift+Enter draws it. It is drawn collapsed, as a box with its name; the <b>Show the code</b> checkbox in its properties expands it. Errors tell you their line.",
  "11c8rik1l": "<b>Suggestions</b> (<code>ƒx</code> button or Ctrl+Space)",
  "1t2uz2arn": "A list under the cursor with what exists <b>at that place in the page</b>: variables and functions defined before, dimensions, libraries inserted before (after <code>UF.</code>, their public names) and the A-CAD functions. What is defined further down does not appear: it does not exist there yet. It is not case sensitive (<code>kt</code> finds <code>Kt_(C2)</code>) and the letters in order are enough (<code>csu</code> finds <code>C_(surf)</code>). Beside it, the detail: the drawn definition, the value at that place, or the help and an example; the help of a script is the <code>#</code> lines that follow its signature. With the list open, Enter or Tab accept, the arrows choose and Esc closes it without deleting what you typed. While you type the values of a function, a pill above the entry shows its signature with the current argument highlighted. In <b>Settings → Suggestions while typing</b>: automatic (they appear after 2 letters; the default on PC and iPad) or on request (the default on the phone).",
  "x292yhd": "Blue badge",
  "1x7feho3h": "Next to the corner of the entry: <code>α</code> is an equation, <code>A</code> is plain text and <code>{}</code> a script.",
  "1u79r4he9": "<b>They close themselves</b>: the closing character appears and the cursor stays in the middle (<code>[|]</code>). Typing the closing character when it is already ahead just moves past it; deleting inside an empty pair deletes both; with text selected, it wraps it. <code>$</code> inside <code>$|$</code> gives <code>$$|$$</code>. They do not close before a letter or a number, nor <code>&lt;</code> inside a formula (it is \"less than\"), nor the <code>$</code> or the <code>`</code> that close something already open. It also works in the Text field of the properties.",
  "1gs64ov10": "<code>\\</code> and a letter, or Ctrl+G",
  "5gas9313a": "<b>Greek letters</b> without a Greek keyboard. <code>\\a</code> becomes α when you type the letter (Backspace right after leaves <code>\\a</code>). Ctrl+G converts the letter before the cursor (again turns it back) or everything selected; on the Mac it is also Ctrl, not Cmd. Table: <code>a</code> α, <code>b</code> β, <code>c</code> χ, <code>d</code> δ, <code>e</code> ε, <code>f</code> φ, <code>g</code> γ, <code>h</code> η, <code>i</code> ι, <code>j</code> ϕ, <code>k</code> κ, <code>l</code> λ, <code>m</code> μ, <code>n</code> ν, <code>p</code> π, <code>q</code> θ, <code>r</code> ρ, <code>s</code> σ, <code>t</code> τ, <code>u</code> υ, <code>v</code> ϖ, <code>w</code> ω, <code>x</code> ξ, <code>y</code> ψ, <code>z</code> ζ; <code>D</code> Δ, <code>F</code> Φ, <code>G</code> Γ, <code>J</code> ϑ, <code>L</code> Λ, <code>P</code> Π, <code>Q</code> Θ, <code>S</code> Σ, <code>V</code> ς, <code>W</code> Ω, <code>X</code> Ξ, <code>Y</code> Ψ. Capitals that look the same as a Latin letter (Α, Β, Ε…) and the ο are not converted. If the next letter can start a symbol or the name of a Greek letter (<code>\\in</code>, <code>\\to</code>, <code>\\al</code>…), it goes back to <code>\\i</code> and the word is typed as is; when you finish it, a symbol stays (<code>\\in</code> is drawn ∈), the name of a Greek letter becomes the letter (<code>\\alpha</code> α) and anything else is the Greek letter plus the rest, as before (<code>\\an</code> αn).",
  "1xj787zp": "Assign and show values",
  "1ctr5tt2n": "Each line of an equation is a statement. The value updates by itself when the drawing changes.",
  "chljc83g": "<b>One statement per line</b>: whatever is left over on the line is marked with ⚠ (<code>x:2  y:3</code>). To put two, use Shift+Enter.",
  "1p95ehl4m": "It is not an output if the line ends in <code>==</code>, <code>&lt;=</code>, <code>&gt;=</code>, <code>!=</code> or <code>:=</code>: there the <b>=</b> is part of the operator.",
  "16q2yz533": "An assigned vector or matrix already shows its value: in <code>v:1..3;3=</code> the final <b>=</b> adds nothing.",
  "1fpf5h361": "An output can read dimensions (including read-only ones and the magnitudes of vectors), variables, and the functions and constants of \"Functions and operators\". An angle dimension is worth its measure in radians.",
  "1flwafx4c": "While editing you see <code>expr=</code>; the drawing and the exports (SVG, DXF) show <code>expr=valor</code>. The magnitude of a vector shows only the value.",
  "1vq6ia92t": "Assigns to <b>x</b> the value of an expression. <code>x:=valor</code> is drawn, just as you typed it.",
  "c48xj410": "The same, typing <code>:=</code>.",
  "3a2th6n": "A <b>=</b> at the end of the line shows the value, with up to 3 decimals. From 1e6 it is shown in scientific notation (<code>2.569e6</code>, 4 significant figures); the threshold is changed in <b>Settings → Scientific notation from</b>.",
  "802r918": "Assigns and shows the value on the same line.",
  "rzsr2hj": "Scientific notation",
  "z0i6q54j": "<code>2.5e6</code> is 2.5·10⁶ and <code>3e-4</code> is 0.0003 (also with <code>E</code>). A very small number is shown with 4 significant figures instead of 0.",
  "1xt16ycb6": "<b>Unit</b>: the value is given in that unit. Units are converted and propagated: <code>F*2</code> stays in N. There are SI units with prefixes (m, g, s, A, K, mol, N, Pa, J, W, V, Ω, Hz, L, bar; k, M, G, c, m, µ, n...) and other common ones (min, h, rpm, atm, psi with prefix such as kpsi, ksi, kgf, lbf, kip, in, ft, lb, hp, gal, deg, rad, %). If the value already carries units, it only says in which unit to show it.",
  "by2rp61r": "With <code>=</code> the calculated value is shown in that unit.",
  "9fg8qm2p": "Units inside an expression. A compound unit goes in parentheses: <code>3'(m/s)</code>.",
  "1azjnss1y": "Shows the value in the requested unit (of the same magnitude; otherwise ⚠).",
  "1aiygfsh": "Automatic unit",
  "1jr6wzcht": "With no unit requested, the result comes out in the unit of a text variable in the expression or in the usual one of the document's unit system (<b>Settings → Units</b>): in SI mm or m, mm² or m², N or kN, N·mm, N·m or kN·m, MPa; in imperial in or ft, in² or ft², lbf or kip, lbf·in, kip·in or kip·ft, psi or ksi. It moves to the larger unit when the number reaches 1000 and stays in it as long as the value is 1 or more (3200 mm is 3.2 m; 1963.5 mm² stays in mm²). A dimension with a unit does not decide the unit of the result: D2 of \"126 in\" gives <code>D2=3,2004 m</code> in SI. Moment and energy are shown as moment (N·m); <code>='J</code> asks for joules.",
  "12w45wwn": "Units that do not match",
  "2ceq80by": "Adding, subtracting or comparing different magnitudes gives ⚠, just like a number without units added to one with units. The exception is <b>0</b>: it is valid with any unit (0 m = 0 kN), so <code>x>0</code> with x in in, <code>x+0</code> or <code>[0, x]</code> work, and a function such as <code>if(x>a; x-a; 0)</code> works with or without units. Functions (sin, ln...) require numbers without units; sqrt, abs and round keep them.",
  "wf3x7ah": "Angle with unit",
  "xfx4ez3i": "<code>deg</code>, <code>°</code> and <code>rad</code> make an angle. In a dimension, a length with units is converted to mm.",
  "1jnmh5h4f": "<b>Range</b>: n values from a to b, a row vector. With a decimal point it is also written <code>x:a..b,n</code>; with a decimal comma, always with <code>;</code>.",
  "8vvqipf": "Range with step.",
  "1wlsu9tj": "Vector with units",
  "oonix175": "One unit for all the elements: <code>[1,2,3]'mm</code>, <code>[1'm, 20'cm]</code> or a range <code>0..10;5'mm</code>. All are shown in the same unit, and a graph uses them in that unit (the legend says so). Mixing magnitudes in a vector gives ⚠.",
  "1osy6xig": "Your own units",
  "wc3ijiis": "A line <code>cantidad:cantidad</code> with exactly one new unit, on either side, defines that unit: <code>1'vuelta:2π'rad</code>, <code>1.70'm:1'persona</code>, or <code>1'persona:'persona</code> (the same unit on both sides) for a new magnitude that does not mix with any other. It applies to the whole drawing, wherever it is (it does not follow the reading order), with letters, _ and numbers (not starting with a number) and without prefixes. It cannot redefine a unit that already exists, with or without prefix: <code>1'in:30'mm</code> or <code>1'mm:'mm</code> give ⚠, and so does defining the same unit twice. Only proportional units (no offset zero, like °C).",
  "1fn6y7o7": "Angles",
  "80cfla8f": "According to <b>Settings → Angles in</b>. In degrees (older drawings), a value with π is an angle in radians and one without π is a plain number: <code>sin(30)</code> is in degrees. In radians (new drawings), everything is in radians: <code>sin(π/6)=0.5</code>. The example is in a drawing in degrees.",
  "oi9k3lh": "Decimal separator",
  "1vb62jnjo": "According to <b>Settings → Decimal separator</b>. With <b>point</b> (<code>1.5</code>) function arguments are separated with a comma, <code>max(2.5, 3)</code>, and in a matrix elements are separated with a comma and rows with <code>;</code>: <code>[1, 2; 3, 4]</code>. With <b>comma</b> (<code>1,5</code>) arguments are separated with <code>;</code>, <code>max(2,5; 3)</code>, and in a matrix elements with <code>;</code> and rows with <code>|</code>: <code>[1; 2 | 3; 4]</code>; indices too, <code>A_(1;2)</code>, and ranges, <code>x:0,5..2;10</code> (with a point: <code>x:0.5..2,10</code>). When you change it, the formulas already in the drawing are rewritten; older drawings, without the option, accept both forms.",
  "1jx51eb74": "<b>Continues on the next line</b>, as in Python: <code>...</code> at the end of a line and, if you want, at the start of the next one. The two lines are a single statement and are drawn like that, split. Useful for an equation that runs past the page margin.",
  "apl35a14": "<code>(</code> or <code>[</code> open",
  "17ap6p39e": "<b>Continues without</b> <code>...</code> while a parenthesis or a bracket is open (also as in Python): the indentation does not count and it looks as if it were on a single line. Useful for writing a matrix or a <code>solve([ecuaciones], [incógnitas])</code> in columns, with one equation per line. The text is saved as you typed it.",
  "1vks92p5": "Error",
  "1qzwrl61v": "If the expression cannot be calculated, ⚠ appears instead of the value.",
  "1iahogf9": "Complex numbers",
  "1p02coi7e": "A complex result is shown as <code>3+4j</code> (<code>j</code> is the imaginary unit; see <a href=\"funciones.md#complex-numbers\" data-help=\"funcs\" data-topic=\"Complex numbers\">Complex numbers</a> in Functions). The root of a negative number is a complex number.",
  "1mtatlpy": "Plain text, formulas and literals",
  "pwb9764p": "A text that starts with <code>\"</code> (or with a space) is drawn as is, except what goes between dollar signs, which is mathematical and calculates just like an equation.",
  "157mstku": "Inline formula, within the text.",
  "co2ajz2b": "Block formula: each line inside is an equation, centered and at full size.",
  "fe0hw46": "<b>Literal</b>: it is drawn but never calculated or read as an assignment or output. Without the quotes, <code>f:\\RR-&gt;\\RR</code> would be an assignment.",
  "1i94fatq": "<code>`…</code> unclosed",
  "16dg6qtf": "It is marked with ⚠.",
  "5j1jqf16": "A dollar sign that does not open a formula.",
  "1ipkfs2l": "Lone <code>$</code>",
  "s53nfo2t": "It is not a formula: <code>$5 y $6</code> is drawn as is. An unclosed <code>$$</code> too, with ⚠.",
  "8eeuvbr": "Markdown in plain text",
  "129cbr46g": "In a plain text (one that starts with <code>\"</code> or a space), whatever is outside the formulas accepts Markdown. The marks do not cross a formula: <code>**a $x$ b**</code> is not bold; write <code>**a** $x$ **b**</code>.",
  "15otpfef": "<b>Bold</b>.",
  "1r0xqs42k": "<i>Italic</i>. The <code>_</code> inside a word does not count (<code>mi_archivo</code>).",
  "j5dyn1w": "<b><i>Bold and italic</i></b>.",
  "u4axg18": "Strikethrough.",
  "1d6w9cl2i": "Monospaced font. In an equation, on the other hand, backticks make a literal.",
  "ss646b3r": "<code># </code>, <code>## </code>, <code>### </code>, <code>#### </code>, <code>##### </code>, <code>###### </code> at the start of the line",
  "1w1ifdc2j": "Heading, in bold and larger (1.6, 1.35, 1.15, 1.05, 1 and 0.9 times the text height).",
  "1va1logz": "A line and <code>===</code> below it",
  "npmt7935": "Also a level 1 heading. On the other hand, <code>---</code> below a text is always a rule, not a heading.",
  "1kk48l31x": "<code>- </code>, <code>* </code>, <code>+ </code> at the start of the line",
  "10kqtp71h": "Bullet. Two spaces before for each level of indentation.",
  "10dv6um1o": "<code>- [ ] </code>, <code>- [x] </code> at the start of the line",
  "1yvqo3ys": "Task: ☐ pending, ☑ done.",
  "o7zckn1i": "<code>1. </code>, <code>1) </code> at the start of the line",
  "zt71r31l": "Numbered list (the number is drawn just as it is typed).",
  "138z3j12": "<code>&gt; </code> at the start of the line",
  "18uah6f2d": "Quote, with a line on the left; <code>&gt;&gt; </code> is a quote inside another.",
  "bfhy9oab": "<b>Callout</b>, with the line and the title in color; the <code>&gt; </code> lines that follow are its body. Without a title the type is shown: <code>note</code>, <code>info</code>, <code>tip</code>, <code>important</code>, <code>warning</code>, <code>caution</code>, <code>danger</code>, <code>example</code>, <code>question</code>, <code>success</code>, <code>quote</code>…",
  "171w57xx": "<code>---</code> alone on the line",
  "1uknpvn2h": "Horizontal rule the width of the text (<code>***</code> and <code>___</code> also work).",
  "cr6d3fw": "<code>```</code> before and after",
  "17rfcai5q": "<b>Code block</b>: monospaced, in a box, with no Markdown or formulas inside (<code>~~~</code> also works). Four spaces at the start of the lines, after a blank line, do the same.",
  "1mc1qx61i": "<code>| a | b |</code> and below it <code>|---|:-:|</code>",
  "1y9mzim7e": "<b>Table</b>: the first row is the header (in bold); the second gives the alignment of each column (<code>:--</code> left, <code>:-:</code> center, <code>--:</code> right). Cells accept formulas; <code>\\|</code> is a bar inside a cell.",
  "23371jdk": "Link, in blue and underlined. Also <code>[texto][ref]</code> with <code>[ref]: url</code> on another line (that line is not drawn) and <code>&lt;https://…&gt;</code> or <code>&lt;correo@dominio&gt;</code>. <b>To open it</b>: one tap selects the text and shows above it a pill with the real destination of each link; tap the pill, or the link with the text already selected. Ctrl or Cmd + click opens it right away. Dragging still moves the text and a double tap opens its properties.",
  "1r6mxfa63": "Web page (in another tab), email or call. <code>www.algo.com</code> is taken as <code>https://</code>. <code>javascript:</code>, <code>data:</code> and other destinations are not opened: the pill shows them struck through.",
  "28llxv8s": "A place in the drawing: the view goes to it and selects it. The title of a text works (<code>## Gráficas !!!</code> is reached with <code>#graficas</code>, without accents, capitals, spaces or signs), the first line of a text or the identifier of an element (<code>#t17</code>, <code>#g94</code>, <code>#p5</code>).",
  "jbi0609f": "Another drawing from the configured GitHub repository (File → GitHub), with the path relative to its folder (<code>sub/a.json</code>, <code>../otra/b.json</code>, <code>/raiz.json</code> from the root). It asks first, because unsaved work is lost. With <code>#lugar</code> at the end (<code>cicloide.json#rueda</code>), it also goes to that place.",
  "1kgr9pa1y": "Image: the drawing does not load images, it shows ▣ and its alternative text.",
  "vcnrd07p": "<b>Icon of an app tool</b>, inside the line, at the height of the letter and in the color of the text. The names are in the help, section \"Icons in texts\" (tap a row to copy it). If the name does not exist it looks like an image: ▣ and the alternative text.",
  "rnjz433n": "<b>Footnote</b>: the call mark goes in superscript, numbered in order, and the notes are gathered at the end of the text in smaller type.",
  "1bmrnkk1j": "Comment: not drawn (can span several lines).",
  "109n87e6x": "Leaves the sign as is (works with any punctuation sign): <code>\\*</code>, <code>\\_</code>, <code>\\#</code>, <code>\\[</code>… A <code>*</code> between spaces (<code>2 * 3</code>) is already left as is, but <code>2*3*4</code> puts the 3 in italics.",
  "g7a7cff": "Line breaks",
  "haqn6wbd": "Every line break is a line break, with or without a page (unlike Markdown, consecutive lines are not joined). With the page (Settings → Page), a line that does not fit is wrapped at the margin, and the left margin is a hard limit: a horizontal text does not start to its left or get dragged past it (graphics can still cross it). A <code>\\</code> at the end of a line is not drawn.",
  "1q09xdjw": "Math notation (AsciiMath)",
  "1cu1hok7t": "Formulas follow the syntax of <a href=\"https://asciimath.org/\" target=\"_blank\" rel=\"noopener\">asciimath.org</a>. They are drawn with fractions, roots, subscripts and mathematical symbols, and they rotate and export (SVG, DXF) like any text. Parentheses grow with what they enclose.",
  "97updc9": "Drawn as",
  "nw0anbeo": "Unlike AsciiMath, without <code>\\</code> a word is converted only if it is <b>entirely</b> a Greek letter, a function, <code>if</code>/<code>and</code>/<code>or</code> or <code>sqrt</code>, <code>abs</code>, <code>norm</code>, <code>floor</code>, <code>ceil</code>, <code>root</code>, <code>frac</code>, <code>text</code>, <code>color</code>; otherwise it is drawn letter by letter: <code>pi r</code> is π r, but <code>pir</code> is three letters, and so is <code>sinx</code> (write <code>sin x</code> or <code>sin(x)</code>).",
  "749p771c": "There is no alignment by <b>=</b> between lines yet.",
  "jgke2419": "Fraction (the parentheses around a and b are not shown).",
  "wh8z05o": "Superscript and subscript.",
  "1d8tvdq7": "Roots.",
  "8kbqxaf": "Greek letters.",
  "1sr2j8m3b": "Sum, product, integral and limit (with <code>\\</code>; <code>sum(v)</code> without it is the calculation function).",
  "221zfo22": "Function names (those of AsciiMath and those of the calculation), in upright type.",
  "71o9lg1d": "≤ ≥ ≠ → ⇒ ± ÷ ∉ (typed with signs, without <code>\\</code>).",
  "1hns49cnr": "<b>Named symbols</b>: ∈ → ∠ × ∞ ≪ ≠ ≤ ∀ ℝ. They take a <code>\\</code> in front, as in LaTeX; without it they are letters (<code>total</code>, <code>line</code> and <code>gain</code> have no → or ∈ inside). When you type <code>\\in</code>, the <code>\\i</code> does not turn into ι: the editor waits to see whether a symbol follows. They are for <b>drawing</b>: in a formula only <code>\\cdot</code>, <code>\\times</code> and the logical operators (<code>\\and</code> <code>\\or</code> <code>\\not</code> <code>\\xor</code>) are calculated. For everything else write the operator (<code>&lt;=</code> <code>&gt;=</code> <code>!=</code> <code>*</code> <code>/</code>) or its character (<code>≤</code> <code>≥</code> <code>≠</code> <code>≈</code> <code>×</code> <code>÷</code>): <code>\\le</code>, <code>\\ne</code>, <code>\\xx</code> or <code>\\div</code> are drawn but give an \"Invalid character\" error when calculating.",
  "4oiky01g": "Absolute value, floor, ceiling and norm, with their bars.",
  "1yzrxxtt": "Accents, underline and strikethrough.",
  "925rqm3h": "Matrices and column vectors drawn (not calculated). Inside brackets, <code>;</code> separates rows and <code>,</code> columns.",
  "1ozq1cqh": "Augmented matrix.",
  "1te6mypm": "System of equations.",
  "1asepvo15": "Braces and signs with something above or below.",
  "va29ya6": "Color.",
  "1ukbklp1x": "Fonts: bold, blackboard, calligraphic, typewriter, fraktur, sans-serif.",
  "zsjnmwx": "Upright text inside the formula.",
  "1jy88lca": "Derivatives.",
  "9xuhdk": "Variable names",
  "1027nto2j": "They follow the rules for Dimension names: letters, numbers and _, starting with a letter.",
  "l91rc16l": "A text with an invalid name, or that uses a variable that does not exist yet, is rejected when you write it (\"undone\"). If it arrives some other way (when pasting a text, for example), that definition is left with ⚠ and the variable undefined from there on.",
  "d5ixwr1r": "Names update on their own if you rename a Dimension that they use.",
  "933kbe3s": "Name with a <b>text subscript</b>: inside parentheses, free text without parentheses or braces. It is drawn with the subscript in upright type.",
  "1y7lfi78o": "Name with a <b>prime</b> at the end (<code>Se'</code>, <code>Se''</code>, <code>σ'_(a)</code>, and functions such as <code>f'(x)</code>). The quote is a prime if what follows cannot start a unit (<code>Se'=</code>, <code>Se'*2</code>); attached to a unit it is still a unit: <code>x'm</code> is x in meters.",
  "1wod6qce": "Greek letters",
  "1qe9qjddk": "They are typed with the letter or with its AsciiMath name, and it is the <b>same variable</b>: <code>beta</code> is <code>β</code>, <code>Delta_1</code> is <code>Δ_1</code> (<code>phi</code> is ϕ and <code>varphi</code> is φ, as they are drawn). <code>pi</code> is still the constant. To type the letter: <code>\\</code> and the letter (<code>\\b</code> → β) or Ctrl+G (see <a href=\"07-texto-y-calculo.md#write-a-text-t\" data-help=\"calc\" data-topic=\"Write a text (T)\">Write a text</a>).",
  "1k6q2mra": "Reserved",
  "18xy54f9c": "A name cannot be a program function or constant (<code>sin</code>, <code>pi</code>…) or match the name of a Dimension. <code>t</code> is time, and <code>j</code>, <code>α</code>, <code>θ</code>, <code>ω</code> (also written <code>alpha</code>, <code>theta</code>, <code>omega</code>) are reserved for future use.",
  "anyn90g": "Reading order",
  "u561eh6r": "The page is read <b>from top to bottom</b> and, within the same row, <b>from left to right</b>: inside a text, line by line; texts, by their top left corner. A variable has the value of the <b>last definition read before it</b>.",
  "lprsfg5c": "<b>Dimensions with a formula</b> (<code>D2 = k*2</code>) are read at the place of their <b>label</b>: if <code>k:1</code> is above the Dimension and <code>k:7</code> further down, <code>D2</code> is 2.",
  "njlevm2y": "Moving a text or a Dimension label (in Select) recalculates the Dimensions that read text variables.",
  "mfp8cj5z": "While simulating or dragging, the reading order of the Dimensions stays <b>frozen</b>: a label that crosses a text does not change its value or stop the simulation. When you release or finish, the normal order returns.",
  "fb2dn02v": "If the text with the definition is deleted, the Dimensions that read it keep their value and lose the formula.",
  "s7fsvr9": "Redefine",
  "azy4iw1a": "A variable can change value further down.",
  "1a4wlp6h": "Using itself",
  "sr5nxw1a": "A redefinition can read the previous value.",
  "1rm3f6us": "Clear: <code>clear()</code>",
  "yu3f301f1": "<code>clear(k)=</code> clears the text variable k from that point of the reading (further down or further right it no longer exists, unless it is defined again); <code>clear(a, b)=</code> clears several (with a decimal comma, <code>clear(a; b)=</code>) and <code>clear(all)=</code> all the variables and functions of the texts defined before. It shows 1 if all the ones it names existed there and 0 if any did not (the ones that existed are cleared anyway). It also clears a <b>Dimension</b> or a <b>drawing measure</b> (<code>clear(D1)=</code>, <code>clear(l3.len)=</code>): from that point they are no longer read (a formula or an output that reads them further down gives ⚠), but they still govern the drawing, and the name is free for a text variable (<code>D1:7</code>). If there is a text variable with that name, the first <code>clear</code> clears the variable and a later one clears the Dimension; a cleared Dimension is not read again further down. If the text variable was named like a Dimension, when it is cleared the name is left empty (⚠) up to the place on the page where the Dimension label is: from there on the Dimension applies. <code>clear(all)=</code> (or <code>clear()=</code>) clears <b>everything</b>: text variables and functions, Dimensions and drawing measures. It is reversible by position: if something breaks further down, remove the <code>clear(all)</code> and clear only what applies. The page works like a timeline: <code>clear</code> clears what exists up to that point, and a Dimension whose label is further down has its value again from its label. Drawing measures (<code>l3.len</code>, <code>p1.x</code>) have no place on the page: once cleared they do not come back. It is useful for closing the scope of a variable, such as a scale eF: a Dimension or a vector that reads it further down gives ⚠ instead of using an old value. <code>clear</code> and <code>all</code> cannot be used as names.",
  "1fzwo891d": "System in columns: <code>solve([…], […])</code>",
  "1jn24iieo": "The same resolution with two vectors: <code>solve([ec1; ec2; ec3], [x; y; z])=</code>, the equations and the names of the unknowns, each in a column. It is useful when the system is large and does not fit on one line of the page. The answer is a column vector <code>[x=…; y=…; z=…]</code>. With a decimal comma, rows are separated with <code>|</code> and the two vectors with <code>;</code>: <code>solve([ec1 | ec2]; [x | y])=</code>. The same rules of the previous row apply (initial value, units, goals on the drawing).",
  "oau6luu": "Solve: <code>solve()</code>",
  "17a499u1at": "<code>solve(ec1; ec2; x; y)=</code> solves a system of equations: those with <code>==</code> are the equations and the bare names are the unknowns. Each unknown must be defined earlier with its <b>initial value</b>, which sets its unit (<code>x:1'm</code>); from that point of the reading it has the solution value, and the output shows it. It is solved numerically from the initial values: with several solutions it gives the closest; if it does not find one, it gives ⚠ and warns (try other initial values). There must be at least as many equations as unknowns. For a single equation inside a formula there is <code>fzero(ecuación; x; inicial)</code>. <b>Goals on the drawing</b>: if the unknowns are Dimensions, the app moves those Dimensions until the equations are met, and the equations can read drawing measures (read-only Dimensions, <code>l3.len</code>, <code>p1.x</code>) and text variables. With the height D5 of a rectangle fixed, <code>solve(D4*D5 == 1200'mm^2; D4)=</code> adjusts the width D4 so that the area is 1200 mm², also if you change D5 later. The initial value is the one each Dimension has, and the goal is met again with each change (when dragging, when editing another Dimension). It is useful for what is not a measure you can constrain: an area, a product or a quotient of Dimensions, a physics formula. If the goal is a distance or an angle in the drawing (a diagonal measuring 50 mm), it is better to make that Dimension driving: the geometric solver solves it directly and faster. The unknowns must move the drawing: neither read-only nor with a formula, and all Dimensions or all text variables. If there is no solution, the change is not made. <code>solve</code> cannot be used as a name.",
  "jxwzwpl": "Use before defining",
  "1b5ughf21": "It does not exist yet: it warns that it \"is defined further down or further right\".",
  "h8z3nna": "Read Dimensions",
  "1ji4kc02k": "A definition can use the Dimensions and variables read before it, and is recalculated when they change.",
  "1mqan1zj": "Vectors and matrices",
  "lpvts982": "They are written in brackets: the comma separates the elements of a row, the semicolon starts another row, and decimals use a point. They are drawn with real brackets and without commas; here they are written with commas, as in \"Functions and operators\", where the full list of operations is.",
  "z85ewq1e": "A range of more than 8 elements is abbreviated with \"…\".",
  "6s5cjd34": "<code>*</code> is the matrix product: two row vectors give an error (use <code>.*</code> or <code>x*y^T</code>).",
  "dtjdx333": "A name that already exists as a variable (<code>x_1</code>, <code>k_(total)</code>) is that variable, not an index.",
  "lv7qj84c": "A Dimension can read an element or a summary (<code>D1 = x_2</code>), but not a whole vector or matrix: it warns with a message. The same in Graphs.",
  "o75wty30": "A matrix written over several lines of a <code>$$</code> block is split by lines: write it on a single line.",
  "1md3vm22e": "Matrix. <code>[1, 2, 3]</code> is a row vector and <code>[1; 2; 3]</code> a column one.",
  "f4z8n87p": "<b>Block</b> matrix: the elements can be vectors or matrices already defined. <code>,</code> puts them side by side (same number of rows) and <code>;</code> one below the other (same number of columns). With two rows V and M, <code>[V; M]</code> is the system matrix.",
  "1drqqvi17": "Transpose: of a row vector, the column one.",
  "4nx2mr14": "Element of a vector, counting from 1.",
  "14di8hs13": "Element of a matrix (row, column).",
  "12js6l2u": "A whole row or column.",
  "1qjfbh9s": "Solve the system A·x = b.",
  "111054jh": "Custom functions",
  "p1jo4p36": "Parameters have the value they are given (numbers, vectors or matrices) and hide variables with the same name.",
  "16xbx184f": "The names of the function and its parameters follow the rules for variables, and cannot be program functions (<code>sin</code>, <code>sum</code>…).",
  "aheatc3j": "Defines a function. It is drawn <code>f(x):=…</code> and used in outputs, variables and Dimensions (<code>D1 = f(3)</code>).",
  "15a81pw1t": "Several parameters, separated by <code>;</code> or <code>,</code>.",
  "crq6yu1r": "Recursion: only the chosen branch is calculated (up to 200 levels).",
  "t6j4tc4l": "Defines the function and shows <code>f(x)</code> right there, with the variables that have a value at that point (if a parameter is not a variable at that point, it shows nothing).",
  "1woc1mx14h": "A <b>drawing object</b> reaches a function of your own by its name (<code>f(l5)</code>, <code>f(a8)</code>, <code>f(k1)</code>) and <code>typeof(x)</code> says what it is. Its points are read by their role, the same ones the element tree shows: <code>o.a</code> and <code>o.b</code> in a line; <code>o.c</code> (center), <code>o.a</code> (start) and <code>o.b</code> (end) in an arc; <code>o.c</code> in a circle. Each point has <code>o.a.x</code> and <code>o.a.y</code>, and the element its properties (<code>o.len</code>, <code>o.ang</code>, <code>o.r</code>). A spline has <code>s.n</code> points and <code>s_i</code> is the i-th; a contour group has <code>k1.n</code> elements, and <code>k1_i</code> is the i-th (<code>k1_i.len</code>, or stored: <code>o:k1_i</code> and then <code>o.a.x</code>). A group (<code>g1</code>) has <code>g1.n</code> objects and <code>g1_i</code> is the i-th; its bounding box, and a contour's, is <code>g1.xmin</code>, <code>g1.xmax</code>, <code>g1.ymin</code>, <code>g1.ymax</code>, <code>g1.w</code> (width) and <code>g1.h</code> (height). A text has <code>t3.x</code> and <code>t3.y</code>. With <code>varargin</code> they arrive of any type. What a branch of an <code>if</code> does not use does not fail when read (<code>k.n</code> in one branch and <code>o.c.x</code> in another): it only fails if that branch runs with an object that lacks it. Careful: <code>e</code> is Euler's constant, it does not work as a name.",
  "1vcqm7vkx": "Optional values: <code>varargin</code> (the last parameter) receives the extra ones, of any type, and they are read with <code>varargin_1</code> or <code>varargin_(k)</code>; <code>nargin</code> is how many values the function received (in any function, <b>counting the fixed parameters too</b>: with <code>f(a; varargin)</code>, <code>nargin-1</code> are those of <code>varargin</code>). With <code>if(nargin==1; …; …)</code> a default value is given. If what arrives is a <b>point of the drawing</b> (<code>p5</code>), its coordinates are read with <code>varargin_1.x</code> and <code>varargin_k.y</code> (or it is stored in a name without an underscore, <code>q:varargin_1</code>, and <code>q.x</code> is read; a name with an underscore is an index and takes no \".x\").",
  "zhzazki": "Outside variables",
  "1gbqhky1v": "It reads the variables that have a value where it is called, not where it was defined.",
  "1no95ehj": "Properties with \".\"",
  "1su2aoh3v": "They are used in any formula: Dimensions, texts (<code>p12.x=</code>), actuators and Graphs. The measures they read update with the drawing.",
  "1j04o6q6": "What it is",
  "vorr0eo": "Coordinates of a point.",
  "xd5hca1b": "Length of a line and its angle, in radians.",
  "xw7cm13": "Radius, diameter and center of a circle.",
  "1ceywm7q": "Radius and center of an arc.",
  "1k7qr0e4l": "An ellipse: its center, its semi-axes (1 is the one of point a and 2 is given by the distance from b to axis 1; 1 is not always the major one) and the angle of axis 1, in radians.",
  "ulp69p44": "An elliptical arc: how much it sweeps from its start to its end counterclockwise, as the parametric angle of the ellipse (a full ellipse does not have it).",
  "1wldl5v3n": "Perimeter of a contour group (the sum of its elements) and its area, which only exists if the elements form a closed chain.",
  "pztea926": "A group: how many objects it has and its bounding box (width, height and extremes).",
  "6ofhq3157": "<b>By its name</b>: a point, a line, a circle, an arc, an ellipse, a spline, a group or a contour is called in formulas by the name you give it in <b>Properties → Name</b>, just like by its id (<code>ini.x</code> is <code>p12.x</code>), and it also reaches an own function by its name (<code>f(ini)</code>, <code>typeof(Brida)</code>). The name takes letters and numbers, starts with a letter and may carry a subscript (<code>iso_1</code>, <code>p_(ini)</code>); it cannot look like an id (<code>p12</code>), nor be repeated, nor be a dimension, a text variable or function, or a reserved word, and the other way round: defining a variable or function with the name of an element gives ⚠ (it says which element already has the name); nothing shares a name. When you change an element's name, the formulas that used it are updated (dimensions, texts, actuators and graphs; programs with <code>%</code> are not changed automatically and the app warns you). The local variables and parameters of a program do not count. A group or contour with a name of another form (<code>Vista frontal</code>) is only used by the tree. Each \"Manual run\" names its group with the function it calls and a number (<code>ort2iso_1</code>, <code>ort2iso_2</code>; <code>script_1</code> if it draws directly). A copy (paste, mirror, arrays) is a new object: it does not inherit the name and is seen by its id. If two elements end up with the same name (only by editing the file by hand), neither can be called by it.",
  "g3qsymq": "Font and text format",
  "lthodj9": "Property",
  "1jr9eo46": "Font",
  "5h6hjj7i": "It is chosen when creating the text or in its properties (double tap on the text): system, Helvetica/Arial, Times/Georgia, Courier/Menlo, Verdana, Palatino, Optima, Futura, American Typewriter and three handwriting fonts. If the device does not have one, a similar generic one is used.",
  "6zquxbb": "Properties",
  "1jmizb7a3": "Everything about the text is changed with a <b>double tap</b> on it: content, color, font, height, angle, alignment with a line, <i>Readable</i> and insertion point. If other texts are selected, the change (except the content) also applies to them, and the height, angle, font, <i>Readable</i> and insertion point are kept for new texts.",
  "anml9mi": "Insertion point",
  "mw16eb2m": "It is a real point: it can be dimensioned, fixed or related. Its place is chosen in the text box.",
  "42eb5jf": "Angle and height",
  "bga1v844": "Rotates and scales the text. <b>Align with</b> aligns it with a line (the angle becomes an offset); \"None\" releases it and keeps the orientation.",
  "1biy5m6e": "<i>Readable</i>",
  "gd4qvn17": "Rotates 180° a text that would end up upside down.",
  "18frvfip": "Show only the result",
  "1csp0bhe8": "In a text that is just <code>expr=</code>, it draws the value without the formula: a number, a table or a message. If the result is a string or a vector of strings, it comes out as normal text, one line per string and with its spaces, in the font of the text: useful for a console or a board. A vector of strings that starts and ends with <code>\"```\"</code> is drawn as a code block (in the chosen font, or monospaced if none was chosen). It only applies if the text has nothing more than that output.",
  "1wcnqshd": "Color and background",
  "1fmoxhs98": "The same swatches serve for the font or the background: it is chosen with <b>Font color</b> or <b>Background color</b>. The background paints the text box (with a small margin) and covers what is underneath; in the background, <i>Auto</i> is the paper color and <b>No background</b> removes it. It shows in the drawing and in the SVG; the DXF does not carry it.",
  "1uhc2rvs": "Drawings from before v2.0",
  "1tfp67222": "When opened, the old syntax is converted to the new one just once, with a notice.",
  "zzj52m5": "Before",
  "ft32qh8": "What happens",
  "16un70x5": "Result",
  "4lndwp16": "Definition: becomes a formula with assignment.",
  "1vahbes19": "Output: becomes a formula with <b>=</b> at the end.",
  "17wtzn0d": "Old formula",
  "1kp5m21v": "What would now be read as an assignment or an output is left as a literal.",
  "1j18cwf7": "Function",
  "od2yra2": "Gives",
  "1yrdzo4m": "Functions and operators",
  "17g1zzman": "Everything a formula accepts, in Dimensions, Texts (`x:…` and `expr=`), actuators and Graphs. Each example shows what it gives; all are checked against the app's engine in the automated tests (`test/funcref.test.mjs`). How formulas, variables and the reading order work is explained in [6. Dimensions](06-cotas.md) and [7. Text and calculation](07-texto-y-calculo.md).",
  "y7tvq91t": "[Index](README.md) · [7. Text and calculation](07-texto-y-calculo.md)",
  "1y1nzg1a": "Operators",
  "wvoma62f": "They work in Dimensions, Texts (<code>x:…</code> and <code>expr=</code>), actuators and Graphs.",
  "10g0v9q4q": "Addition, subtraction, multiplication and division. Also <code>÷</code>; between two vectors, <code>·</code> is <code>dot</code> and <code>×</code> is <code>cross</code> (see below).",
  "1m1r8v89": "Power.",
  "53g1ld9": "Implicit",
  "hle37c1r": "A number next to a parenthesis, π or a name multiplies.",
  "l1giwmu": "Square root of what follows.",
  "1fkchjo2k": "They separate the values of a multi-argument function. <code>2,5</code> without a space is the number 2.5.",
  "k8bet13e": "They compare: give 1 if true and 0 if not. Also <code>≤ ≥ ≠</code>. <code>==</code> and <code>!=</code> tolerate rounding.",
  "14nkv7xj6": "Logical operators. With a backslash they are drawn as a symbol and calculate the same: <code>\\and</code> ∧, <code>\\or</code> ∨, <code>\\not</code> ¬, <code>\\xor</code> ⊕ (also <code>\\land \\lor \\lnot \\wedge \\vee \\neg \\oplus</code> and the characters <code>∧ ∨ ¬ ⊕</code>); without a backslash they are drawn as a word. A value is true if it is not 0; they give 1 or 0. Order: comparison first, then <code>not</code>, <code>and</code> and finally <code>or</code> and <code>xor</code>. <code>and</code> and <code>or</code> do not calculate the second side if the first already decides (like the branch <code>if</code> does not choose), so <code>n &gt; 0 and f(n-1) &gt; 0</code> can call itself. They are reserved words.",
  "wuw2w633": "If the condition <code>c</code> is not 0 the value is <code>a</code>, otherwise <code>b</code>. It only calculates the chosen branch.",
  "qln6dhbz": "Almost equal: 1 if |a − b| ≤ tolerance × max(1, |a|, |b|), otherwise 0. The tolerance (1e-12 by default) is changed in <b>Settings</b>. Use it to compare rounded results; <code>==</code> remains the app's equality. With the same tolerance, a unitless result (or each element of a vector or matrix) other than 0 with |x| ≤ tolerance is shown as <code>≈0</code> (rounding noise, not an exact zero).",
  "16nga95a": "Constants",
  "dkxv4916": "Pi. A value that carries π is in radians.",
  "kze3isg": "Euler's number.",
  "13ctuwhd": "Trigonometry",
  "1p97g1sf1": "The angles in <b>calculation texts and Graphs</b> follow the drawing option <b>Settings → Angles in</b>: in <b>radians</b> (new drawings: <code>sin(π/2)</code> gives 1) or in <b>degrees</b> (older drawings, which do not have the option: <code>sin(30)</code> gives 0.5). In degrees, if the argument carries π or is a drawing angle (an angular dimension such as <code>A1</code> or <code>l3.ang</code>) it is in radians. <b>Dimensions</b> and actuators always use degrees; in an angular dimension in radians, everything is in radians.",
  "ej0pdao": "Sine, cosine and tangent.",
  "wk7zp5j": "With π, in radians.",
  "7byiaf1g": "Secant, cosecant and cotangent, with the same rule.",
  "u8ykmn1w": "Inverses: return degrees (radians if the drawing is in radians).",
  "lavbfz1d": "Angle of the point (x, y) in degrees, from −180 to 180.",
  "1kjjihgv": "Hyperbolic (they do not use angles).",
  "qta7i0l": "From radians to degrees.",
  "w9i24ql": "From degrees to radians.",
  "10tud3w2g": "Like sin, cos and tan, but the angle is always in degrees (regardless of the drawing's mode).",
  "jozl3219": "Inverses, with the result always in degrees.",
  "bsckmsu": "Roots, powers and logarithms",
  "vq09j8e": "Square root.",
  "1jwai9ne": "e raised to x.",
  "w11jnsi": "Natural logarithm.",
  "nygyhul": "Base-10 logarithm.",
  "q3erl6f": "Absolute value.",
  "1os4oz2h": "Sign: −1, 0 or 1.",
  "10qwpsix": "Square root of the sum of squares.",
  "1j03h073j": "Real n-th root: with negative x and odd n it gives a negative (x^(1/n) would give a complex number). With units: nthroot(27'm^3; 3) = 3 m.",
  "vdcq7hk": "Base-2 logarithm.",
  "729o1sr": "Rounding, minimums and maximums",
  "4laeyk28": "Rounds to <code>n</code> decimals (0 if omitted). Halves round away from zero.",
  "1xf0dwlj": "Integer rounded down.",
  "12lewhnk": "Integer rounded up.",
  "100au7ak": "Removes the decimals.",
  "zawdas12": "Remainder of a divided by b, with the sign of b.",
  "ysg2l412": "The smallest and the largest of several values.",
  "4maz7on": "Clamps x to the interval.",
  "1j9znl6r": "Toward zero (like trunc).",
  "3h5mtu1m": "Remainder of a divided by b, with the sign of a (mod takes the sign of b).",
  "38ctr41j": "Greatest common divisor and least common multiple (integers).",
  "yxvbo0p": "n! (n an integer from 0 to 170).",
  "l856r8o": "Combinations of n taken k at a time.",
  "1lf541y7a": "Uniform random numbers in [0, 1): one, an n×n or n×m matrix (<code>rand(1; 200)</code>, a row). The sequence is <b>reproducible</b>: each calculation of the drawing starts from the same seed, so an output and its graph show the same values.",
  "1xhn3b3l": "Like rand, with a standard normal distribution (mean 0, deviation 1). For mean μ and deviation s: <code>μ + s*randn(1; n)</code>.",
  "1i1b8ls1u": "Random integers from 1 to imax, or from a to b; with n and m, a matrix.",
  "vv2wqga6": "Changes the seed of rand, randn and randi from that point of the reading: another sequence, also reproducible. With <code>\"shuffle\"</code>, a new seed with each change of the drawing (and with each step of <code>wfile</code>): for a game or a simulation that must not repeat. Between changes it is kept: the screen is redrawn with the same draw. The seed is what counts.",
  "hy7dxx77": "They are written in square brackets: the comma separates the elements of a row, the semicolon starts another row, and decimals use a point. They are used in Texts (<code>A:[1,2;3,4]</code>, <code>A=</code>); a dimension can read an element (<code>D1 = x_2</code>).",
  "188ch3ft": "Row vector and column vector.",
  "uu9shy4x": "By blocks: the elements can be vectors or matrices. The comma puts them side by side (same number of rows) and the semicolon one below the other (same number of columns).",
  "s7irq61o": "Range: <code>n</code> values from a to b, both included.",
  "1plt3y1o": "Range with step, not going past b (the step can be negative).",
  "1skk9s32a": "Element, counting from 1. The indices can be formulas: <code>x_(i+1)</code>.",
  "1nezbemj": "Row i and column j.",
  "h7eko5c": "Transpose.",
  "vmlro11r": "Between matrices of the same size, or a number with each element.",
  "11j71f015": "Matrix product (or number times matrix).",
  "vsu28uk": "Element by element.",
  "12umx9bl": "Single-argument functions",
  "1wbs21m19": "On a matrix, they apply to each element.",
  "66f4cw1c": "Inverse (warns if it is singular or not square).",
  "1phf2l813": "Integer power of a square matrix.",
  "xjgdpfd": "Determinant.",
  "1fkmfour": "Trace: sum of the diagonal.",
  "1eb5p2d1p": "From a vector, the diagonal matrix; from a matrix, its diagonal.",
  "xag6ao": "n×n identity matrix.",
  "ustf4r12": "Rows, columns and number of elements.",
  "rj7fc13": "Sum and product of all the elements.",
  "9pwz5lg": "Mean and median.",
  "urjgq21i": "Sample standard deviation and variance (divided by n−1).",
  "rok4j81a": "Euclidean norm (Frobenius for a matrix).",
  "14k5wg11d": "With a single vector: its smallest and largest element.",
  "u6pu12r": "Cumulative sum and product.",
  "qjjrl59": "Dot product. Also written <code>a · b</code> (or <code>a ⋅ b</code>), in any orientation except column by row (<code>a · bᵀ</code>), which is the outer product, a matrix.",
  "kk22hl51": "Cross product of 3-element vectors. Also written <code>a × b</code>. With three vectors, <code>a×b×c</code> and <code>a·b×c</code> are ambiguous and give an error: use parentheses.",
  "1x590bb21": "Distance between two points (vectors of the same size, with their units).",
  "g8za6ru": "Building and reordering matrices",
  "a327qx1l": "Those that reorder keep the units and the complex numbers.",
  "1xzf7bb1h": "Matrix of zeros or ones (n×n with a single value).",
  "132q3jl1p": "n evenly spaced values from a to b (100 if n is omitted).",
  "ao1y021u": "n values from 10^a to 10^b on a logarithmic scale (50 if n is omitted).",
  "1i3f8jx21": "Number of elements (also of a string vector); [rows, columns].",
  "q9b4htn": "Transpose (like A^T).",
  "1ojgl4hy": "Sorts a vector from smallest to largest.",
  "s41sl92h": "Reverses the order: a vector; the columns (left-right); the rows (top-bottom).",
  "1mi0qug6d": "Repeats A n times downward and m times to the right. With a string or a vector of strings (a vector of strings is a list, with no rows or columns) it gives n·m copies in a list: <code>repmat(\"\"; 1; 24)</code> is 24 empty strings.",
  "4iqmeo1e": "The same elements as n×m, taken column by column.",
  "bi48bi4u": "Side by side and one below the other (like [A, B] and [A; B]). With strings and vectors of strings it joins them into a single vector of strings: <code>nm:horzcat(nm; \"x\")</code> makes it longer.",
  "a1brh0m": "Kronecker product.",
  "96m8eks": "1 if any element is not 0.",
  "1q29ma4x": "The positions (from 1; in a matrix, column by column) of the elements that are not 0; 0 if there are none. With a comparison, which elements meet it: <code>find(v > 100)</code>.",
  "frmrsqe": "Linear algebra",
  "1n58ms72k": "With real numbers (inv, det, linsolve and eig also with complex numbers). eig supports up to 12×12.",
  "1n1q96y1q": "x such that A·x = b. If A is not square, by least squares.",
  "1uxpb7i6": "Rank.",
  "bfnvp19": "Condition number (using singular values).",
  "ev93051o": "Pseudoinverse (works with singular or non-square matrices).",
  "liwd7u1i": "Eigenvalues, in a column; complex if there are any.",
  "131tf7t10": "Differences, cumulative sums and integrals",
  "qjp5fx11": "Differences between consecutive elements.",
  "rn0lg4r": "Running maximum and minimum.",
  "c8ddqi19": "The most frequent value (with a tie, the smallest).",
  "1newj6222": "Trapezoidal integral of data (and cumulative). With a single vector, step 1.",
  "ycw84a4e": "Integral of an expression in the variable x, between a and b (numerical, adaptive). As in fzero, the variable is named. With units: those of expr times those of x.",
  "1wd26f2q": "Interpolation and polynomials",
  "ncnyrz2m": "A polynomial is the vector of its coefficients, from highest degree to lowest: [1, 0, -2] is x² − 2.",
  "mkrq725m": "Linear interpolation in a table (x a number or a vector; keeps the units of ys). Outside the table it gives ⚠; with <code>interp1(xs; ys; x; \"extrap\")</code> it extrapolates using the first or last segment.",
  "1yb15frp": "Value of the polynomial at x.",
  "1c7ismv13": "Roots (column); complex if there are any.",
  "1mg99hg17": "Degree-n polynomial by least squares.",
  "1fchh1tn": "Product of polynomials.",
  "43krui12": "Derivative and integral (with constant 0).",
  "16wkums3k": "They are defined in a text and used in outputs, variables and dimensions. They can call other functions and themselves.",
  "5fliy8o": "Function of one parameter.",
  "19203exh": "Complex numbers",
  "733wlwiz": "<code>j</code> is the imaginary unit (<code>3+4j</code>); a number can also take the suffix: <code>2.5j</code> or <code>2.5i</code> (the letter <code>i</code> alone is still a variable). The square root of a negative number gives a complex number: <code>sqrt(-4)</code> is <code>2j</code>, <code>ln(-1)</code> is <code>πj</code>, and a negative base with a non-integer exponent gives a complex number. Operations, powers, functions (sin, exp, ln, sqrt…), matrices (inv, det, product) and units (an impedance in Ω) all work. Complex numbers can only be compared with <code>==</code> and <code>!=</code>. A dimension, a graph or the condition of an if needs a real number: abs, angle, real or imag give one.",
  "nzt0sf7": "Modulus (absolute value).",
  "1a89q181e": "Argument (in degrees or radians, depending on the drawing).",
  "818wv0o": "Real and imaginary part.",
  "1vr52jgs": "Conjugate: z·conj(z) = |z|².",
  "1uky5ag7": "Strings",
  "1nxatrfdf": "A string goes between quotes: <code>\"Cumple\"</code> (the iPad's curly quotes “ ” work too; <code>\"\"</code> inside is one quote). They are joined with <code>+</code> and compared with <code>==</code> and <code>!=</code>; a number is converted with <code>num2str</code> (with its unit). <code>[\"a\", \"b\"]</code> is a string vector (<code>v_2</code> is the second). In the result they are shown in typographic quotes. For a check message: <code>if(σ&lt;Sy, \"Cumple\", \"No cumple\")</code>.",
  "1k0oa8l2i": "A number as text, with its unit and as the app shows it (n fixed decimals if given).",
  "1jnxpdt2n": "Format: %d, %f, %.2f, %e, %g, %s, %%. Without units: divide by the unit you want (F/1'kN).",
  "1sbq8rlw": "The number written in a string.",
  "1ukzt0ml": "Joins strings (like +).",
  "702yxlkr": "What arrived in a function: <code>\"number\"</code>, <code>\"string\"</code>, <code>\"strings\"</code>, <code>\"matrix\"</code>, <code>\"complex\"</code>, or a drawing object (<code>\"point\"</code>, <code>\"line\"</code>, <code>\"circle\"</code>, <code>\"arc\"</code>, <code>\"ellipse\"</code>, <code>\"spline\"</code>, <code>\"contour\"</code>, <code>\"group\"</code>), a text (<code>\"text\"</code>) or a dimension (<code>\"dimension\"</code>). <code>isa</code> gives 1 if it is of that type and 0 if not; <code>isa(x; \"earc\")</code> gives 1 only for an elliptical arc (which <code>typeof</code> also calls <code>\"ellipse\"</code>, like the full ellipse: ask about <code>\"earc\"</code> first). They work with <code>varargin</code>: <code>if isa(varargin_1; \"line\"): …</code>.",
  "1a7eocv5e": "Stops the calculation with that message, to validate what a function receives: <code>else: error(\"solo se admite T, L o R\")</code>. The message is flagged in the text, with the name of the function.",
  "2grxy11r": "Uppercase, lowercase, trimmed of spaces at the ends, reversed.",
  "13yihdjw": "Replaces all occurrences.",
  "1tzlm952u": "1 if the string is empty (or all of those in a string vector); a number or a vector is never empty.",
  "1pjpibc2k": "Splits a string into a string vector (by spaces if sep is not given) and joins them back.",
  "1f5r8r6l": "Number of characters.",
  "bix4311l": "1 if the string contains, starts with or ends with the pattern.",
  "1d35ol91q": "Positions (from 1) where the pattern appears; 0 if it does not appear.",
  "uuresd1i": "1 if they are equal (strcmpi, ignoring case).",
  "196he7a3h": "What comes before or after a pattern (or a position), or between two; with two numbers, between those positions (inclusive).",
  "10gusgjl": "Between two positions.",
  "e09z939": "Programs",
  "trl27tad": "Steps in order and loops inside a formula. Inside, <code>s:valor</code> assigns a <b>local</b> variable: it is valid only in that formula (it does not create document variables or change those outside). They can be written on several lines, with indentation, and are drawn as written. A loop is capped at 100,000 iterations and 1.5 s: if it exceeds that, it warns instead of freezing the app.",
  "11lc6lo15": "Does the steps in order and takes the value of the last one.",
  "1yv51f33y": "Repeats the body with i = inicio, inicio+1, … up to fin (if fin < inicio, zero times). With a vector instead of the range, i takes each element.",
  "11n7hqk2u": "Repeats the body while the condition holds. For several steps in the body, <code>seq(…)</code>.",
  "5v4qn55o": "Inside a for or a while: <code>break()</code> exits the loop; <code>continue()</code> moves on to the next iteration. In a script they are written alone on their line: <code>break</code>, <code>continue</code>.",
  "vrneio2p": "Ends the function (or the script) with the value x, without going on. In a script, <code>return x</code>.",
  "49y9tcac": "Assigns an element of a vector or matrix (or of a string vector) inside a program, on a local copy: the document variable does not change outside. An index past the end extends the vector with zeros (useful for building a vector in a <code>for</code>). The value takes the vector's magnitude; a vector of unitless zeros takes that of the first value.",
  "j05jbhn": "Drawing from a script",
  "pojyyj2hy": "A calculation text can <b>draw</b>: <code>point</code>, <code>line</code> and <code>circle</code> create points, lines and circles and return their <b>name</b> (a string), which is how the others refer to them. What is generated is governed by the script: its points are fixed, they are identified by their name (local to the text that draws them; from another text you use the <b>variable</b> that holds it, without quotes: <code>s1:line(p5, pto2)</code>, and it knows which text it comes from; in a spline and between quotes the name is still local to the text) and they update on their own when the variables the script reads change. You can put dimensions and constraints on them, but you cannot move, trim or delete them by hand: you change the call, or you switch the text to <b>Manual run</b> (checkbox in its properties): the text sits in a frame with a ▶ button, draws only when you press it, and what it draws is <b>free</b> (normal elements, in a new group, with no link to the script: you can move, delete and constrain them, and they are not regenerated). Each press adds another group, it does not replace the previous one. When you tick the checkbox, what the text already drew live is released as it is (same elements, with their dimensions and constraints). A <b>function of yours</b> can also draw: you call it by assigning the result, <code>r:f(x)</code> (a statement with \"=\" only displays and does not draw); <code>r</code> is what the function returns and what it creates inside is named like <code>r.pa</code>, <code>r.pb</code>…, after its local variable. A point of the drawing (<code>p5</code>) or a generated one is passed as an argument, and inside the function reads <code>p.x</code> and <code>p.y</code>. What the function drew in its local variables is read from outside as part of <code>r</code>: <code>r.pa</code> is the point and <code>r.pa.x</code> its coordinate (it also works as an argument: <code>line(r.pa; q)</code>); local numbers (<code>w</code>) do not come out, they stay local. A point you drew yourself (<code>p5</code>) also works as an endpoint of a line, an arc or a spline, or as the center of a circle: <code>line(p5; pto2)</code>; if you move it, what is drawn follows it (with an arc, its two endpoints must stay at the same distance from the center). A dimension between two generated things becomes a reference dimension. If you remove a call, what it drew disappears. The variable that holds what you draw has the same properties as the drawing elements: <code>p.x</code>, <code>p.y</code> on a point; <code>l.L</code> (or <code>l.len</code>) and <code>l.ang</code> on a line; <code>c.r</code>, <code>c.d</code>, <code>c.x</code>, <code>c.y</code> on a circle; <code>r</code>, <code>x</code>, <code>y</code> on an arc. They are computed from what the script asked for (not read from the drawing), are valid further down in the reading order and, if a variable has the same name as a drawing element (<code>p1</code>), the variable wins. As always in the reading order, the script goes above or to the left of whatever reads it. If the text reads a reference dimension that measures what the text itself draws, it is a loop: the app warns and leaves what was generated as it was. When you select something generated, the status bar says which text it comes from (tap it to see it) and the text is highlighted.",
  "1vzbpkha6": "Creates a point at (x, y), in drawing units, and returns its name. It is fixed. Without a label it is named after the variable you assign it to (<code>a:point(10; 5)</code> is the point \"a\"); if one statement creates several (a for, a function), the first takes that name and the others \"a#2\", \"a#3\"… With the label, the name is the one you write. The name is local to the text.",
  "i6hn6u4j": "A line between two points already created with point (by name or by the variable that holds it). The line type is optional (\"eje\", \"oculta\"…); without it, continuous.",
  "1co59tg2n": "A circle centered at the point c (created with point) and radius r. The line type is optional.",
  "1bu2jmx5d": "An arc centered at the point c with ends a and b (created with point), from a to b counterclockwise. a and b must be at the same distance from c, which is the radius. Optional line type.",
  "xl42pa5b": "An ellipse with center c, a at the end of axis 1 and b at a point of axis 2 (its distance to axis 1 is the semi-minor axis); all three are points created with point. With an optional line type.",
  "zeber34f": "The elliptical arc of that ellipse that goes from p1 to p2 counterclockwise; p1 and p2 must lie on the ellipse (if not, the app warns). With an optional line type.",
  "qumo295p": "A spline through the named points (at least 2), created with point. A second string \"cerrado\" (closed) closes it (at least 3 points); another one is the line type: <code>spline([\"A\", \"B\", \"C\"]; \"cerrado\"; \"eje\")</code>.",
  "18jh1dxjl": "Groups as a <b>contour</b> the elements you give: variables that hold a line, an arc, an ellipse or a spline drawn by the script (at least 2). A loose string is the name of the group: <code>k:contour(ab; bc; cd; da; \"perfil\")</code>. It is defined by the <b>elements</b> and not by the points, because several can pass between two points (a line and an arc) and one point can be in more than one contour. The group is generated like what it groups: change the elements of the call and its members change; if you remove the call, it dissolves and its elements are left loose. If an element was not drawn, or is already in another group, the app warns. It is assigned like the others (<code>k:contour(…)</code>).",
  "1qim3kn1o": "A rectangle that depends on w and h: change them and it redraws.",
  "u8zooya": "Equations",
  "y0f2j8b9": "They are solved numerically (Levenberg-Marquardt): starting from an initial value, it looks for the value that satisfies the equation. With several roots it gives the one closest to the initial value; if it finds none, it warns. For a system of equations, <code>solve(…)=</code> in a text (see <a href=\"07-texto-y-calculo.md#reading-order\" data-help=\"calc\" data-topic=\"Reading order\">Reading order</a> in Text and calculation).",
  "1fcw4b96d": "The value of x that satisfies the equation, written with <code>==</code> (<code>x^2 == 2</code>) or as an expression equal to 0 (<code>x^2-2</code>). The initial value carries the units of x; without it, it uses the value of x at that point, or 1.",
  "itq0bj29": "With units: the force that gives a moment of 30 kN·m with an arm of 2 m (in kN).",
  "18ia88uj": "Data between drawings",
  "1y1b5apap": "They store a value to read it later or from another drawing. The data lives in this browser, on this device (File → Data shows, exports and imports it). They are written when a change to the drawing is confirmed, not while dragging or in the simulation; rfile always reads what is stored, so with <code>c:rfile(n)</code> and <code>wfile(c+1; n)</code> each change adds 1 and the last stored value is shown.",
  "1e1gwetay": "Stores the value (a number with its unit, a vector, a matrix or a string) in the data file <i>Name</i> and equals 1. The name is not evaluated: it is that of a variable (its value does not matter, nor whether it exists) or a string with an extension, <code>\"datos.txt\"</code>. The file is text with A-CAD syntax and a decimal point: <code>12'kN</code>, <code>[1, 2; 3, 4]'mm</code>, <code>\"texto\"</code>.",
  "hlh8wc3w": "The value stored with <code>wfile</code>, with its units: <code>q:rfile(MiVariable)</code> gives 12 kN. If there is no data with that name, it gives ⚠.",
  "7y7ejw4w": "What is stored or, if there is not yet any data with that name, <i>inicial</i> (which is only calculated then): useful for getting started, <code>c:rfile(n; 0)</code>. It is an A-CAD extension.",
  "11njcnw8o": "Equals 1 in the step started by an Enter on the text that defines <i>nombre</i> (in in-place editing, even without changing it) and 0 in any other step: opening the drawing, moving something, editing another text. To run a command when it is confirmed: <code>wfile(si(entered(orden); hacer(x; orden); x); Estado)</code>.",
  "1opfil47": "Sounds",
  "gikxv5az": "Audio files in the device's data folder (File → Data…: they are imported with a name, tested, exported and deleted). When imported they are downsampled (one channel, 16 kHz, 8 bits): about 16 KB per second. The drawing embeds those it names in quotes, <code>play(\"nombre\")</code>, and restores them on opening if they are missing; a name built from a variable does not travel with the drawing.",
  "117uxfmdh": "Plays the drawing's sound with that name, once, in the step that confirms a change to the drawing (an Enter in a text: the same step in which <code>wfile</code> runs). It does not play on redraw, on dragging, on opening the drawing or in the simulation. Equals 1 if the drawing has that sound and 0 if not (no error), and it can be used inside a function or a library: <code>if(choca; play(\"explosion\"); 0)</code>. Browsers only allow sound after a tap or a key press.",
  "e78ss9i": "Drawing values",
  "dce5l82g": "Names that a formula can read. They always equal what the drawing has at that moment.",
  "1sqp0yk2t": "Named dimensions: distance, angle (in radians), radius and diameter. The name can be changed.",
  "1e40l8f1z": "Length of a line and its angle (from its start to its end, in radians).",
  "1f5p4v323": "Variables of the texts, read from top to bottom and from left to right.",
  "13i8mfv18": "Time, in actuators and graphs.",
  "1cqt43g2j": "In graphs: the displacement of an actuator (also <code>.d</code>) and its velocity.",
  "iijm3l4w": "They cannot be used as a dimension or variable name: the functions and constants in this list, <code>t</code>, <code>j</code>, <code>ω</code>, <code>θ</code> and <code>α</code>.",
  "djczzfcx": "<p>A text can show the icon of a tool, to refer to it in a tutorial or a note: <code>![Línea](icon:line)</code> draws it inside the line, at the height of the letter and in the color of the text (in a link, in blue). What goes between the brackets is the alternative text: it is used if the name does not exist and in other Markdown viewers. It is also exported (SVG and DXF, as strokes). <b>Tap a row to copy it</b> and paste it into the text.</p>",
  "1v2f3g63g": "<p>Complete list of what a formula accepts, in dimensions, texts, actuators and graphs. Each example shows what it gives.</p>",
  "11e87opf": "Text and calculation",
  "1bkclhsk": "Icons in texts",
};
